from datetime import datetime, date, timedelta
from bisect import bisect_left


MONTH_NAMES = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

DOW_NAMES = {
    "SUN": 0, "MON": 1, "TUE": 2, "WED": 3,
    "THU": 4, "FRI": 5, "SAT": 6,
}


def _is_decimal_digits(value: str) -> bool:
    return bool(value) and all("0" <= c <= "9" for c in value)


def _parse_step(value: str) -> int | None:
    if not _is_decimal_digits(value):
        return None
    n = int(value)
    return n if n >= 1 else None


def _parse_value(token: str, low: int, high: int, names: dict[str, int] | None) -> int | None:
    if names:
        key = token.upper()
        if key in names:
            value = names[key]
            return value if low <= value <= high else None

    if not _is_decimal_digits(token):
        return None

    value = int(token)
    return value if low <= value <= high else None


def _parse_field(field: str, low: int, high: int, names: dict[str, int] | None, weekday: bool = False) -> list[int]:
    if field == "":
        raise ValueError

    values = set()

    for item in field.split(","):
        if item == "":
            raise ValueError

        if item == "*":
            values.update(range(low, high + 1))
        elif "/" in item:
            if item.count("/") != 1:
                raise ValueError

            left, right = item.split("/")
            step = _parse_step(right)
            if step is None:
                raise ValueError

            if left == "*":
                values.update(range(low, high + 1, step))
            else:
                bounds = left.split("-")
                if len(bounds) != 2:
                    raise ValueError

                a = _parse_value(bounds[0], low, high, names)
                b = _parse_value(bounds[1], low, high, names)
                if a is None or b is None or a > b:
                    raise ValueError

                values.update(range(a, b + 1, step))
        elif "-" in item:
            bounds = item.split("-")
            if len(bounds) != 2:
                raise ValueError

            a = _parse_value(bounds[0], low, high, names)
            b = _parse_value(bounds[1], low, high, names)
            if a is None or b is None or a > b:
                raise ValueError

            values.update(range(a, b + 1))
        else:
            value = _parse_value(item, low, high, names)
            if value is None:
                raise ValueError
            values.add(value)

    if weekday:
        values = {0 if v == 7 else v for v in values}

    return sorted(values)


def _split_fields(expression: str) -> list[str]:
    stripped = expression.strip(" \t")
    fields: list[str] = []
    buffer: list[str] = []

    for ch in stripped:
        if ch == " " or ch == "\t":
            if buffer:
                fields.append("".join(buffer))
                buffer = []
        else:
            buffer.append(ch)

    if buffer:
        fields.append("".join(buffer))

    return fields


def next_run(expression: str, after: datetime) -> datetime | None:
    fields = _split_fields(expression)
    if len(fields) != 5:
        raise ValueError

    raw_minute, raw_hour, raw_day, raw_month, raw_weekday = fields

    minutes = _parse_field(raw_minute, 0, 59, None)
    hours = _parse_field(raw_hour, 0, 23, None)
    days = _parse_field(raw_day, 1, 31, None)
    months = _parse_field(raw_month, 1, 12, MONTH_NAMES)
    weekdays = _parse_field(raw_weekday, 0, 7, DOW_NAMES, weekday=True)

    if not minutes or not hours or not days or not months or not weekdays:
        raise ValueError

    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)

    month_set = set(months)
    day_set = set(days)
    weekday_set = set(weekdays)

    day_field_specified = raw_day == "*"
    weekday_field_specified = raw_weekday == "*"

    max_year = after.year + 10
    if max_year > 9999:
        max_year = 9999

    start_date = date(after.year, after.month, after.day)
    end_date = date(max_year, 12, 31)

    if start_date > end_date:
        return None

    current = start_date

    while True:
        if current.month in month_set:
            weekday_value = (current.weekday() + 1) % 7

            if day_field_specified and weekday_field_specified:
                day_ok = (current.day in day_set) or (weekday_value in weekday_set)
            elif day_field_specified:
                day_ok = current.day in day_set
            elif weekday_field_specified:
                day_ok = weekday_value in weekday_set
            else:
                day_ok = True

            if day_ok:
                if current == start_date:
                    lower_time = after.hour * 60 + after.minute + 1
                else:
                    lower_time = 0

                index = bisect_left(times, lower_time)
                if index < len(times):
                    h, m = divmod(times[index], 60)
                    return datetime(current.year, current.month, current.day, h, m)

        if current == end_date:
            break

        current += timedelta(days=1)

    return None
